def uncomment(text):
    return re.sub(r'/\*.*?\*/|//[^\r\n]*',lambda m:'\n'*m[0].count('\n'),text,flags=re.S)


def compact(text):return re.sub(r'\s+','',uncomment(text))


def token_digest(text):
    pattern='"(?:[^"\\\\]|\\\\.)*"|(?:\\d+)?\'[sS]?[bBoOdDhH][0-9a-fA-F_xXzZ?]+|[A-Za-z_$][\\w$]*|\\d+|===|!==|<=|>=|==|!=|&&|\\|\\||<<|>>|\\S'
    tokens=re.findall(pattern,uncomment(text))
    return hashlib.sha256(json.dumps(tokens,separators=(',',':')).encode('utf-8')).hexdigest()


def contract(label,text):
    require(label in CONTRACTS,'unknown snapshot protocol source role')
    expected=CONTRACTS[label];clean=uncomment(text);flat=compact(text)
    # Whole normalized source identity closes conditional/priority changes,
    # extra consumers and arithmetic outside the named-signal inventory.
    require(token_digest(text)==expected['NormalizedSHA256'],
        'snapshot protocol compiled implementation differs: '+label)
    inventory={}
    for signal,uses in expected['SignalUses'].items():
        rows=[{'Line':number,'Text':line.strip()}for number,line in enumerate(clean.splitlines(),1)
            if re.search(r'\b'+re.escape(signal)+r'\b',line)]
        require([compact(row['Text'])for row in rows]==uses,'unreviewed snapshot protocol signal use: '+signal)
        assignments=re.findall(r'\b'+re.escape(signal)+r'(?:\[[^]]+\])?\s*<=([^;]+);',flat)
        inventory[signal]={'Occurrences':len(re.findall(r'\b'+re.escape(signal)+r'\b',clean)),
            'AllUseSites':rows,'AssignmentRHS':assignments,'AllUseSitesReviewed':True}
    return {'SourceRole':label,'NormalizedSHA256':expected['NormalizedSHA256'],
        'CompleteImplementationRecognized':True,'CriticalSignals':inventory}


def source_review(build_plan):
    build_plan=Path(build_plan).resolve();plan=build.validate(build_plan)
    work=build.work_path(build_plan.parent);watched={};bindings={};contracts={}
    for key in ('InputSHA256','PreparedSHA256'):
        for path,digest in plan[key].items():build.add(watched,path,digest)
    for label,spec in CONTRACTS.items():
        source=spec['Source'];rows=[r for r in plan['CompiledInputs']if r['Source']==source]
        require(len(rows)==1,'one compiled snapshot protocol source required: '+source)
        row=rows[0];original=build.ROOT/source;compiled=work/'compiled'/source
        build.add(watched,original,row['OriginalSHA256']);build.add(watched,compiled,row['CompiledSHA256'])
        bindings[label]={'Original':ref(original),'Compiled':ref(compiled),'Changes':row['Changes']}
        contracts[label]=contract(label,compiled.read_text(encoding='utf-8-sig'))
    for path in (SELF,Path(build.__file__).resolve(),build_plan):build.add(watched,path)
    ownership=[
        {'Claim':'Single immutable bank; reference reads never release write ownership',
         'SourceRoles':['Top','Memory','Capture','Reference'],
         'Evidence':'A=PCLK write; B=reference read and WEB=0. Capture publishes successful DONE only after complete geometry/all writes/drain, remains FROZEN; only a new successful FROZEN request permits overwrite. Reference issues no next request before LAST_STOP byte_done.'},
        {'Claim':'Every descriptor decision uses a local shadow after DONE and settling',
         'SourceRoles':['Reference'],
         'Evidence':'WAIT_DONE requires fresh done_sync==request_toggle. SETTLE0 then SETTLE1 unconditionally samples held source fields. CHECK_DESC on the next reference edge checks only desc_* shadows, nonzero matching ID, 518400 bytes, 2073600 pixels and good/fault.'},
        {'Claim':'Complete FOV and actual committed byte order precede publication',
         'SourceRoles':['Capture'],
         'Evidence':'WAIT_VS requires subsequent real VS rising after history. CAPTURE checks each 1920-pixel line, 1080 lines and terminal counts on the following VS. One-PCLK wr_valid/address/data feed the actual RAM WE; stored_bytes and CRC update only on ram_we. DRAIN includes three edges before publishing.'},
        {'Claim':'Last UART stop bit completes before bank reuse',
         'SourceRoles':['Reference','UART','Top'],
         'Evidence':'TRAILER only enters LAST_STOP after its last byte handshake. LAST_STOP requires UART done. UART done is asserted only after bit_index=9 has completed BIT_CYCLES; no other in-flight completion source connects byte_done.'},
        {'Claim':'Source descriptor and identity remain held until the next request',
         'SourceRoles':['Capture','Reference'],
         'Evidence':'Successful FROZEN only accepts a new toggle, then SETTLE rejects zero or previous done_id. Request_id increments only in INTERVAL, never wraps FFFFFFFF. Geometry/CRC descriptor has no live frame update after DONE.'}]
    epoch=[
        {'Claim':'Stopped-PCLK reset cannot authenticate retained old DONE',
         'SourceRoles':['Top','Capture','Reference'],
         'Evidence':'Capture and reference share global_reset_n. Capture p_reset asynchronously clears, synchronously releases in two PCLKs and directly masks source_boot_ready/done_toggle/done_good. Reference local reset clears request/id/synchronizers/done_seen; BOOT requires boot_sync and synchronized DONE=0 before any request.'},
        {'Claim':'A fresh source history and request epoch precede every capture',
         'SourceRoles':['Capture','Reference'],
         'Evidence':'First sampled_valid only establishes VS/DE history. Fresh request traverses two PCLK synchronizers plus SETTLE; ID is held and nonzero/different from done_id; WAIT_VS waits for a subsequent true rise. Reference accepts only the matching toggle and shadow ID.'},
        {'Claim':'Timeout or malformed capture never retries, releases or reads stale RAM',
         'SourceRoles':['Capture','Reference'],
         'Evidence':'Capture fault publishes good=0 and stays FAULT; reference invalid descriptor/boot loss/wait timeout/unexpected RAM valid enters sticky failed FAULT. No fault path increments/toggles REQ or returns to INTERVAL. Invalid descriptors are rejected before reads. Once FAULT is reached no later RAM request is issued; a previously scheduled same-edge read may retire but cannot produce an authenticated packet or release the bank. Only common reset restarts.'}]
    def proof(rows):return {'Passed':True,'SourceOnly':True,'Proofs':rows,'Missing':[],'Violations':[],
        'NativeFFConsumersVerified':False,'NativeMemoryModesVerified':False,'PhysicalTimingAccepted':False}
    value={'Schema':SCHEMA,'Target':build.TARGET,'BuildPlan':ref(build_plan),
        'SourceProtocolReviewPassed':True,'SourceOnly':True,'SourceBindings':bindings,'Contracts':contracts,
        'SnapshotOwnership':proof(ownership),'SnapshotEpoch':proof(epoch),
        'NativeVerificationStillRequired':['Actual native source/sink topology and every foreign relationship',
            'Actual RAM port modes/clocks/write-disable and freeze/epoch paths',
            'Exact first-stage scopes, unwaived interstage setup/hold, reset guards and all-ten-table STA'],
        'ConstraintsAuthorized':False,'TimingAccepted':False,'HardwareReleaseAllowed':False,
        'InputSHA256':dict(sorted(watched.items()))}
    require(all(Path(p).is_file()and sha(p)==h for p,h in watched.items()),'snapshot protocol input drift')
    return value,{Path(p):h for p,h in watched.items()}
